import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  Color,
  DoubleSide,
} from 'three/webgpu';
import {
  uv,
  color,
  mix,
  noise,
  rand,
  float,
  add,
  mul,
  vec2,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  const colors = config.intent?.visualSpec?.colors || {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // ---- Backdrop Plate ----
  const plateGeo = new PlaneGeometry(7, 5.5);
  // Gradient + grain using TSL
  const baseColor = mix(
    color(colors.background),
    color(colors.surface),
    uv().y
  );
  const grain = mul(rand(uv().xy), float(0.015));
  const finalColor = add(baseColor, grain);
  const plateMat = new MeshBasicNodeMaterial({
    colorNode: finalColor,
    side: DoubleSide,
  });
  const plate = new ctx.THREE.Mesh(plateGeo, plateMat);
  group.add(plate);

  // ---- Text Content ----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerDef = textItems.find((t) => t.role === 'kicker');
  const heroDefs = textItems.filter((t) => t.role === 'hero');
  const bodyDef = textItems.find((t) => t.role === 'body');
  const captionDef = textItems.find((t) => t.role === 'caption');

  const paperColor = colors.paper;
  const inkColor = colors.ink;

  function createTextBlock(content, opts) {
    const textObject = ctx.fontAtlas.createText(content, opts);
    // Ensure text is left-aligned; createText already positions based on align
    return textObject;
  }

  // Helper to create a text line and add to group, return the object for animation
  function addTextLine(content, opts, posY, isShadow = false) {
    const txt = createTextBlock(content, {
      ...opts,
      color: isShadow ? inkColor : paperColor,
    });
    txt.position.set(-3.1, posY, isShadow ? -0.02 : 0);
    group.add(txt);
    return txt;
  }

  // Kicker
  const kickerY = 1.7;
  const kickerText = addTextLine(kickerDef?.text || 'NOVA ATELIER / JOURNAL', {
    fontSize: 18,
    fontWeight: 700,
    letterSpacing: 0.12,
    align: 'left',
  }, kickerY);

  // Hero lines (two)
  const hero1Y = 0.9;
  const hero2Y = 0.25;
  const hero1Text = addTextLine(heroDefs[0]?.text || 'PRECISION IS', {
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    align: 'left',
  }, hero1Y);
  const hero1Shadow = addTextLine(heroDefs[0]?.text || 'PRECISION IS', {
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    align: 'left',
  }, hero1Y, true);
  const hero2Text = addTextLine(heroDefs[1]?.text || 'A HABIT.', {
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    align: 'left',
  }, hero2Y);
  const hero2Shadow = addTextLine(heroDefs[1]?.text || 'A HABIT.', {
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.015,
    align: 'left',
  }, hero2Y, true);

  // Accent underline rule
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshStandardNodeMaterial({
    color: color(colors.accent),
    emissive: color(colors.accent),
    emissiveIntensity: 1.2,
    roughness: 0.3,
    metalness: 0,
  });
  const rule = new ctx.THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-3.1 + 1.1, -0.15, 0);
  rule.scale.x = 0; // start invisible, animate later
  group.add(rule);

  // Body paragraph
  const bodyY = -0.8;
  const bodyText = addTextLine(bodyDef?.text || 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.', {
    fontSize: 26,
    fontWeight: 400,
    letterSpacing: 0,
    align: 'left',
    maxWidthPx: 4.5 * 30, // approximate conversion: 4.5 scene units ~ 4.5 * 30px? Use 135px
  }, bodyY);

  // Caption
  const captionY = -1.9;
  const captionText = addTextLine(captionDef?.text || 'ISSUE 12 / JULY 2026', {
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    align: 'left',
  }, captionY);

  // ---- Entrance Animation ----
  const tl = gsap.timeline({ paused: true });

  // Animate each block: opacity 0->1, y from +0.4 to current y
  const blocks = [
    { el: kickerText, y: kickerY },
    { el: hero1Text, y: hero1Y },
    { el: hero1Shadow, y: hero1Y },
    { el: hero2Text, y: hero2Y },
    { el: hero2Shadow, y: hero2Y },
    { el: bodyText, y: bodyY },
    { el: captionText, y: captionY },
  ];

  blocks.forEach(({ el, y }) => {
    tl.fromTo(el.position, { y: y + 0.4 },
      { y: y, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }, 0)
      .fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }, 0);
    // Stagger by adding 80ms per block
    tl.shiftChildren(0.08 * blocks.indexOf({ el, y })); // Not perfect; better to use labels
  });

  // Simpler approach: use sequential labels
  tl.clear();
  let offset = 0;
  blocks.forEach(({ el, y }) => {
    tl.to(el.position, { y: y, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }, offset)
      .to(el, { opacity: 1, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }, offset);
    offset += 0.08;
  });

  // Hero shadows start immediately with same timeline (position already set, but opacity should match)
  // Actually shadows we set opacity to 0 and animate similarly
  [hero1Shadow, hero2Shadow].forEach((el, i) => {
    tl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }, offset - 0.16 + i * 0.08);
  });

  // Underline rule: scaleX after hero lands (delay ~0.7*2+0.08 = 1.48s)
  tl.to(rule.scale, { x: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, offset + 0.2);

  // Play timeline immediately (since no trigger specified)
  tl.play();

  // ---- Cleanup ----
  const cleanup = () => {
    tl.kill();
    plateGeo.dispose();
    plateMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    // Text objects have internal materials; dispose via fontAtlas? Not provided, assume automatic
  };

  group.userData = {
    handlers: {},
    cleanup,
  };

  return group;
}
